/* Source: shared/lib/navigation.js; requiredRouteFor. Generated by standalone-build.mjs. */
function requiredRouteFor(target){
    if(intakeSkipped(target)){
      const forward = skipForwardFrom(target);
      // Deep link into a screen this route never asks: the questionnaire is
      // already done, so resolve to whatever follows it.
      if(!forward) return flowState.entryChannel==='partner' ? 'intake-concern' : 'signup';
      target = forward;
    }
    if(target==='intake-concern' && !sharedConcernRequired()) return 'intake1';
    /* Consent is recorded against a verified account. A direct hash or a
       restored browser tab must never expose the end state with all choices
       ticked while the CTA is still disabled because OTP has not happened. */
    if(target==='consent-terms'){
      if(!flowState.accountCreated) return 'signup';
      if(!flowState.otpVerified) return 'otp';
      if(!flowState.passwordSet && !flowState.returningIdentityValid) return 'set-password';
      if(flowState.entryChannel==='partner' && !flowState.partnerPhoneVerified) return 'partner-patient-info';
    }
    if(flowState.entryChannel==='partner' && INTAKE_DRAFT_SCREENS.includes(target)){
      if(!flowState.partnerConsentComplete) return 'consent-terms';
      if(!flowState.partnerInfoComplete || !flowState.partnerPaymentChosen) return 'partner-patient-info';
      if(flowState.partnerPaymentMethod==='insurance' && !flowState.coverage?.policyId) return 'partner-insurance';
    }
    if(PARTNER_SCREENS.includes(target)){
      if(!flowState.partnerConsentComplete) return 'consent-terms';
      if(target!=='partner-idcard' && !flowState.partnerIdStepDone) return 'partner-idcard';
      if(!['partner-idcard','partner-patient-info'].includes(target) && !flowState.partnerInfoComplete) return 'partner-patient-info';
      if(['partner-insurance','partner-phr'].includes(target) && !flowState.partnerPaymentChosen) return 'partner-patient-info';
      if(target==='partner-phr' && !flowState.partnerConcernComplete) return 'intake-concern';
      if(target==='partner-phr' && !flowState.partnerHealthComplete) return 'intake-general';
    }
    if(flowState.entryChannel==='partner' && DIRECT_PRE_DOCTOR_GATE_TARGETS.has(target)
       && (!flowState.partnerReviewComplete || !flowState.partnerReviewConfirmedAt)){
      return requiredRouteFor('partner-phr');
    }
    if(target==='intake-general' && flowState.entryChannel==='direct'){
      if(!flowState.draftReady) return 'intake1';
      if(!flowState.accountCreated) return 'signup';
      if(!flowState.otpVerified) return 'otp';
      if(!flowState.passwordSet && !flowState.returningIdentityValid) return 'set-password';
      if(!flowState.consentsComplete) return 'consent-terms';
      if(!flowState.patientInfoComplete) return 'patient-info';
      // The fee no longer gates this page — it now comes before payment.
    }
    /* Sign-up used to be reachable only after an intake, so "create an account"
       on the log-in page bounced to question one with a warning (client, 20 Sep).
       An account is its own errand; the care screens stay gated by
       REQUIRED_CARE_TARGETS below, which still asks for the intake first. */
    if(target==='set-password' && !flowState.otpVerified && !flowState.passwordResetPending) return 'login';
    if(target==='otp' && !flowState.accountCreated && !flowState.partnerPhoneOtpPending && !flowState.phoneOtpPending) return 'signup';
    if(target==='identity'){
      // Asked for on a route that no longer has this step: send them on.
      if(!identityRequired()) return flowState.patientInfoComplete ? directClinicalStartTarget() : 'patient-info';
      if(!flowState.draftReady) return 'intake1';
      if(!flowState.accountCreated) return 'signup';
      if(!flowState.otpVerified) return 'otp';
      if(!flowState.passwordSet && !flowState.returningIdentityValid) return 'set-password';
      if(!flowState.consentsComplete) return 'consent-terms';
    }
    if(target==='patient-info'){
      if(!flowState.draftReady) return 'intake1';
      if(!flowState.accountCreated) return 'signup';
      if(!flowState.otpVerified) return 'otp';
      if(!flowState.passwordSet && !flowState.returningIdentityValid) return 'set-password';
      if(!flowState.consentsComplete) return 'consent-terms';
      if(identityRequired() && !flowState.identityVerified && !flowState.returningIdentityValid) return 'identity';
    }
    // Insurance details are shared by profile setup and partner entry. Both
    // contexts open this identity check before the ordinary clinical guard.
    if(target==='insurance' && ['profile','partner'].includes(insuranceEntry)) return target;
    /* The last step of the sign-up chain stands in for the whole chain —
       reaching it means everything before it was done. That used to be
       identity; on the direct route it is now the patient record. */
    const signupChainDone = signedIn() || flowState.returningIdentityValid ||
      (identityRequired() ? flowState.identityVerified : flowState.patientInfoComplete);
    if(REQUIRED_CARE_TARGETS.has(target) && !signupChainDone){
      if(!flowState.draftReady) return 'intake1';
      if(!flowState.accountCreated) return 'signup';
      if(!flowState.otpVerified) return 'otp';
      if(!flowState.passwordSet && !flowState.returningIdentityValid) return 'set-password';
      if(!flowState.consentsComplete) return 'consent-terms';
      if(!flowState.patientInfoComplete) return 'patient-info';
      return 'identity';
    }
    if(flowState.entryChannel==='direct' && DIRECT_PRE_DOCTOR_GATE_TARGETS.has(target) && !flowState.directGeneralHealthComplete){
      return 'intake-general';
    }
    return target;
  }

/* Source: shared/lib/intake.js; renderIntakeQuestions. Generated by standalone-build.mjs. */
function renderIntakeQuestions(){
    // One question set per access path. General keeps the broad screening set.
    const byCategory = { 'hair-skin':'hair', skin:'skin', weight:'weight', 'sexual-health':'sexual', 'sleep-stress':'sleep', hormone:'hormone' };
    const key = selectedCategory().general ? 'general' : (byCategory[selectedCategoryId] || 'hair');
    if(renderedIntakeContext === key) return;
    // Template coverage per concern (verified 2026-08-04):
    //   weight / skin / sexual / sleep -> own intake1, intake2, intake3
    //   hair                  -> own intake1, intake2; intake3 falls back to the
    //                            authored base, which is the generic "previous
    //                            care or treatment" set and is concern-appropriate
    //   general               -> own intake1 only, and it carries the whole
    //                            questionnaire; intake2-intake5 are skipped
    // A missing template therefore falls back to the authored base markup only
    // where that base is genuinely generic. Never let it inherit another
    // concern's set: add an explicit template, or add the screen to
    // GENERAL_COMPACT_SKIPPED_SCREENS.
    ['intake1','intake2','intake3','intake4'].forEach(id => {
      const body = document.querySelector(`#${id} .screen__body`);
      if(!body) return;
      // Cache the AUTHORED markup, never the enhanced markup. Reading innerHTML
      // after custom-select has run captures its generated wrapper without the
      // listeners, so restoring that cache produced a select that looked right
      // and ignored every tap until a page refresh rebuilt it.
      if(!intakeBaseMarkup[id]){
        const pristine = body.cloneNode(true);
        if(window.kraneStripSelectEnhancement) window.kraneStripSelectEnhancement(pristine);
        intakeBaseMarkup[id] = pristine.innerHTML;
      }
      const template = (intakeTemplates[key] || {})[id];
      body.innerHTML = template !== undefined ? template : intakeBaseMarkup[id];
      if(window.kraneEnhanceSelects) window.kraneEnhanceSelects(body);
      setupIntakeQuestionPages(id,{reset:true});
      syncIntakeDropdownContinue(id);
    });
    renderedIntakeContext = key;
  }

/* Source: shared/lib/intake.js; setupIntakeQuestionPages. Generated by standalone-build.mjs. */
function setupIntakeQuestionPages(screenOrId,{reset=false}={}){
    const screen = typeof screenOrId === 'string' ? document.getElementById(screenOrId) : screenOrId;
    if(!screen || !INTAKE_ONE_QUESTION_SCREENS.includes(screen.id)) return;
    const body=screen.querySelector('.screen__body');
    if(!body) return;
    /* The compact general intake keeps the description and its "how long"
       qualifier together as one question. The duration fold below also keeps
       that relationship consistent for category-specific intake screens. */
    // The Krane Clinic lockup is chrome, not a question.
    const children=[...body.children].filter(child => !child.classList.contains('intake-lockup'));
    const titleBlock=children.find(child => child.querySelector('.h1')) || children[0];
    /* "How long has this been happening?" is not a question of its own — it
       qualifies the one above it. Fold it into that question so the pair is
       answered together instead of splitting one thought across two pages. */
    children.filter(child => child!==titleBlock && child.classList.contains('intake-duration-field'))
      .forEach(field => {
        const previous=field.previousElementSibling;
        if(previous && previous!==titleBlock) previous.appendChild(field);
      });
    const remaining=[...body.children].filter(child => !child.classList.contains('intake-lockup'));
    const questions=remaining.filter(child => child!==titleBlock);
    questions.forEach((question,index) => {
      question.dataset.intakeQuestion=String(index+1);
    });
    addIntakeQuestionGuidance(screen.id,questions);
    /* The screen title stayed huge on every page while the question itself sat
       in a small grey label — the hierarchy read backwards (client, 18 Aug).
       When a page carries exactly one labelled question, that label becomes the
       page heading and the screen title steps aside. A page that folds two
       prompts together (a description and its "how long") keeps the shared
       title, because neither label speaks for the whole page. */
    questions.forEach(question => {
      question.querySelectorAll('.intake-question__title')
        .forEach(node => node.classList.remove('intake-question__title'));
      const labels=[...question.querySelectorAll('.section-label,.field>label,legend')];
      /* The first label is the page's question and becomes its heading; any
         other prompt on the page (a duration, a unit) stays a small field
         label. Pages used to fall back to the screen title whenever a second
         label existed, so a set with folded durations looked nothing like a
         set without them (client, 19 Aug). */
      question.querySelectorAll('.intake-question__sub')
        .forEach(node => node.classList.remove('intake-question__sub'));
      /* A folded qualifier — "how long has this been happening?" — is never the
         page's question. When the block has no label of its own the screen
         title is the question and stays; the qualifier drops to sub size. It
         was being promoted over the real question, so the page showed two big
         headings (client, 19 Aug). */
      const ownLabels=labels.filter(label => !label.closest('.intake-duration-field'));
      const heading=ownLabels[0] || null;
      if(heading){
        heading.classList.add('intake-question__title');
        question.dataset.intakeQuestionTitled='1';
      } else {
        delete question.dataset.intakeQuestionTitled;
      }
      /* Every follow-up prompt on the page is the same component and gets the
         same look, whether it started life as a section label or a field
         label. */
      labels.filter(label => label!==heading)
        .forEach(label => label.classList.add('intake-question__sub'));
    });
    /* Client, 23 Sep: no counters in the questionnaire. The stepper at the top
       of the screen already says how far along this is; a second "1 / 2" beside
       the question was counting the same journey twice. Any left over from an
       earlier render are cleared here. */
    titleBlock?.querySelectorAll('[data-intake-question-count]').forEach(node => node.remove());
    if(reset || body.dataset.intakeQuestionIndex===undefined) body.dataset.intakeQuestionIndex='0';
    activateIntakeQuestionPage(screen,Number(body.dataset.intakeQuestionIndex || 0));
  }

/* Source: shared/lib/ui.js; ensureAppBarLockup. Generated by standalone-build.mjs. */
function ensureAppBarLockup(id){
    document.querySelectorAll(`#${id} .screen__body > .intake-lockup`).forEach(node => node.remove());
    /* Client, 22 Sep: the lockup belongs on these pages too. A transition stage
       closes with an × instead of going back, so it has no .back and this used
       to skip it — leaving "จับคู่แพทย์" as the only routed page still showing
       its route name where every other page shows the brand. */
    const top=document.querySelector(`#${id} .screen__top:has(> .back), #${id} .screen__top.transition-stage__top`);
    /* Tracking has its own centred order number and right-side actions. Adding
       the common brand lockup here creates a second centre item and overlays
       the order title, so this custom app bar deliberately stays logo-free. */
    if(top?.classList.contains('postpay-tracking-topbar')) return;
    if(!top || top.querySelector(':scope > .checkout-brandbar__logo')) return;
    /* Client, 22 Sep: a bar that already names the thing you are looking at
       keeps that name. Tracking titles itself with the order number, and the
       lockup — centred and absolutely placed — was printed on top of it. */
    if(top.querySelector(':scope > [class$="__title"]')) return;
    let title=top.querySelector(':scope > .ttl');
    if(!title){
      title=document.createElement('span');
      title.className='ttl';
      const anchor=top.querySelector(':scope > .back');
      if(anchor) anchor.insertAdjacentElement('afterend',title);
      else top.prepend(title);
    }
    if(title.querySelector('.intake-lockup')) return;
    const accessibleTitle=title.textContent.trim();
    const lockup=document.createElement('span');
    lockup.className='intake-lockup';
    lockup.setAttribute('aria-hidden','true');
    if(accessibleTitle) title.setAttribute('aria-label',accessibleTitle);
    title.classList.add('ttl--lockup');
    title.append(lockup);
  }

